ALTER TABLE "email_outbox" ADD COLUMN "last_attempt_at" timestamp with time zone;
CREATE TABLE "staff_notifications" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "notification_reference" text NOT NULL UNIQUE, "staff_user_id" uuid NOT NULL REFERENCES "staff_users"("id") ON DELETE cascade, "event_key" text NOT NULL, "category" text NOT NULL, "title" text NOT NULL, "body" text NOT NULL, "destination" text NOT NULL, "dedupe_key" text NOT NULL UNIQUE, "read_at" timestamp with time zone, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE INDEX "staff_notifications_staff_read_created_idx" ON "staff_notifications" ("staff_user_id", "read_at", "created_at");
CREATE TABLE "staff_notification_preferences" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "staff_user_id" uuid NOT NULL REFERENCES "staff_users"("id") ON DELETE cascade, "category" text NOT NULL, "email_enabled" boolean DEFAULT true NOT NULL, "in_app_enabled" boolean DEFAULT true NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "staff_notification_preferences_staff_category_unique" UNIQUE("staff_user_id", "category"));
